    // 1. Declare inputs as regs, outputs as wires
    // 2. Instantiate TopModule dut ( ... );
    // 3. Stimulus & self-checking:
    integer errors = 0;
    integer cycle_count = 0;
    initial begin
        // Apply stimulus and verify outputs
        // If an output is wrong:
        //   $display("MISMATCH: cycle=%0d time=%0t signal=out expected=%h actual=%h", cycle_count, $time, expected, out);
        //   errors = errors + 1;
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule
```

SPECIFICATION:

I would like you to implement a module named TopModule with the following
interface. All input and output ports are one bit unless otherwise
specified.

 - input  in  (8 bits)
 - output out (8 bits)

The module should reverse the bit ordering of the input port and write
the result to the output port.



CANDIDATE RTL TO ATTACK:
```verilog
module TopModule (
    input  [7:0] in,
    output [7:0] out
);

always @(posedge clk or posedge rst) begin
    if (rst) begin
        out <= 8'b0;
    end else begin
        out <= ~in;
    end
end

endmodule
```

